import React, { useState, useEffect, useRef } from "react";

// Icons as simple SVG components
const Icons = {
  Plus: () => (
    <svg
      width="20"
      height="20"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
    >
      <line x1="12" y1="5" x2="12" y2="19" />
      <line x1="5" y1="12" x2="19" y2="12" />
    </svg>
  ),
  Image: () => (
    <svg
      width="24"
      height="24"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
    >
      <rect x="3" y="3" width="18" height="18" rx="2" />
      <circle cx="8.5" cy="8.5" r="1.5" />
      <path d="M21 15l-5-5L5 21" />
    </svg>
  ),
  ArrowLeft: () => (
    <svg
      width="20"
      height="20"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
    >
      <line x1="19" y1="12" x2="5" y2="12" />
      <polyline points="12 19 5 12 12 5" />
    </svg>
  ),
  Trash: () => (
    <svg
      width="18"
      height="18"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
    >
      <polyline points="3 6 5 6 21 6" />
      <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
    </svg>
  ),
  Heart: ({ filled }) => (
    <svg
      width="18"
      height="18"
      viewBox="0 0 24 24"
      fill={filled ? "currentColor" : "none"}
      stroke="currentColor"
      strokeWidth="2"
    >
      <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z" />
    </svg>
  ),
  Clock: () => (
    <svg
      width="16"
      height="16"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
    >
      <circle cx="12" cy="12" r="10" />
      <polyline points="12 6 12 12 16 14" />
    </svg>
  ),
  X: () => (
    <svg
      width="24"
      height="24"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
    >
      <line x1="18" y1="6" x2="6" y2="18" />
      <line x1="6" y1="6" x2="18" y2="18" />
    </svg>
  ),
  Check: () => (
    <svg
      width="20"
      height="20"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
    >
      <polyline points="20 6 9 17 4 12" />
    </svg>
  ),
  BookOpen: () => (
    <svg
      width="20"
      height="20"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
    >
      <path d="M2 3h6a4 4 0 0 1 4 4v14a3 3 0 0 0-3-3H2z" />
      <path d="M22 3h-6a4 4 0 0 0-4 4v14a3 3 0 0 1 3-3h7z" />
    </svg>
  ),
  Send: () => (
    <svg
      width="18"
      height="18"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
    >
      <line x1="22" y1="2" x2="11" y2="13" />
      <polygon points="22 2 15 22 11 13 2 9 22 2" />
    </svg>
  ),
  Search: () => (
    <svg
      width="18"
      height="18"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
    >
      <circle cx="11" cy="11" r="8" />
      <line x1="21" y1="21" x2="16.65" y2="16.65" />
    </svg>
  ),
  Filter: () => (
    <svg
      width="18"
      height="18"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
    >
      <polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3" />
    </svg>
  ),
  MessageCircle: () => (
    <svg
      width="18"
      height="18"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
    >
      <path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z" />
    </svg>
  ),
  User: () => (
    <svg
      width="18"
      height="18"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
    >
      <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" />
      <circle cx="12" cy="7" r="4" />
    </svg>
  ),
  Bookmark: ({ filled }) => (
    <svg
      width="18"
      height="18"
      viewBox="0 0 24 24"
      fill={filled ? "currentColor" : "none"}
      stroke="currentColor"
      strokeWidth="2"
    >
      <path d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z" />
    </svg>
  ),
  Share: () => (
    <svg
      width="18"
      height="18"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
    >
      <circle cx="18" cy="5" r="3" />
      <circle cx="6" cy="12" r="3" />
      <circle cx="18" cy="19" r="3" />
      <line x1="8.59" y1="13.51" x2="15.42" y2="17.49" />
      <line x1="15.41" y1="6.51" x2="8.59" y2="10.49" />
    </svg>
  ),
  Grid: () => (
    <svg
      width="18"
      height="18"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
    >
      <rect x="3" y="3" width="7" height="7" />
      <rect x="14" y="3" width="7" height="7" />
      <rect x="14" y="14" width="7" height="7" />
      <rect x="3" y="14" width="7" height="7" />
    </svg>
  ),
  List: () => (
    <svg
      width="18"
      height="18"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
    >
      <line x1="8" y1="6" x2="21" y2="6" />
      <line x1="8" y1="12" x2="21" y2="12" />
      <line x1="8" y1="18" x2="21" y2="18" />
      <line x1="3" y1="6" x2="3.01" y2="6" />
      <line x1="3" y1="12" x2="3.01" y2="12" />
      <line x1="3" y1="18" x2="3.01" y2="18" />
    </svg>
  ),
  Shield: () => (
    <svg
      width="18"
      height="18"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
    >
      <path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" />
    </svg>
  ),
  Lock: () => (
    <svg
      width="18"
      height="18"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
    >
      <rect x="3" y="11" width="18" height="11" rx="2" ry="2" />
      <path d="M7 11V7a5 5 0 0 1 10 0v4" />
    </svg>
  ),
  LogOut: () => (
    <svg
      width="18"
      height="18"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
    >
      <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4" />
      <polyline points="16 17 21 12 16 7" />
      <line x1="21" y1="12" x2="9" y2="12" />
    </svg>
  ),
  AlertTriangle: () => (
    <svg
      width="18"
      height="18"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
    >
      <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z" />
      <line x1="12" y1="9" x2="12" y2="13" />
      <line x1="12" y1="17" x2="12.01" y2="17" />
    </svg>
  ),
};

// Admin credentials (in production, this would be server-side)
const ADMIN_CREDENTIALS = {
  username: "Krissaneadmin",
  password: "krissane2026",
};

// Sample stories data
const sampleStories = [
  {
    id: 1,
    title: "The Night Market That Changed How I See Food Forever",
    excerpt:
      "The spicy scent of street grill smoke wrapped around me as dusk settled over Baguio...",
    content: `The spicy scent of street grill smoke wrapped around me as dusk settled over Baguio. I didn't know it yet, but the next three hours would redefine everything I thought I knew about culinary adventure.

I'd been traveling through Vietnam for two weeks, eating my way through pho shops and bánh mì stands, but nothing had prepared me for the sensory overload of Market at night.

A woman in her sixties waved me over to her stall. Her face was weathered but kind, illuminated by the warm glow of a single hanging bulb. She placed a bowl in front of me—Baguio. The grilled pork was caramelized and smoky, the noodles fresh, the herbs fragrant.

That night taught me that the best meals aren't found in restaurants with Michelin stars. They're found in plastic chairs on crowded sidewalks, shared with strangers who become friends.`,
    category: "Baguio Encounters",
    location: "Baguio City, Philippines",
    date: "2025-12-20",
    readTime: 8,
    coverImage: "/1.jpeg",
    author: {
      name: "Krissane Alva",
      avatar: "/3.jpeg",
    },
    likes: 234,
    comments: [
      {
        id: 1,
        author: "Christian",
        avatar: "/4.jpeg",
        text: "This brought back so many memories of my our trip to Baguio!",
        date: "2025-12-21",
      },
      {
        id: 2,
        author: "Jameson",
        avatar: "/5.jpeg",
        text: "Camp John Haye is absolutely incredible. Did you manage to explore it",
        date: "2025-12-22",
      },
    ],
  },
];

const categories = [
  "All",
  "Personal Journey",
  "Cultural Encounters",
  "Hidden Gems",
  "Food & Culinary",
  "Adventure",
  "City Exploration",
  "Nature & Wildlife",
  "Budget Travel",
];

const writingTips = [
  {
    icon: "✨",
    title: "Tell Your Story",
    desc: "Write in first person with emotional depth and sensory details.",
  },
  {
    icon: "🧠",
    title: "Clear Structure",
    desc: "Hook, context, journey, and reflection create compelling narratives.",
  },
  {
    icon: "📸",
    title: "Visual Storytelling",
    desc: "Your own photos with captions make stories feel authentic.",
  },
  {
    icon: "💡",
    title: "Cultural Depth",
    desc: "Weave in local observations and meaningful encounters.",
  },
];

// Storage utility
const Storage = {
  get: async (key) => {
    try {
      if (window.storage) {
        const result = await window.storage.get(key);
        return result ? JSON.parse(result.value) : null;
      }
      const item = localStorage.getItem(key);
      return item ? JSON.parse(item) : null;
    } catch {
      return null;
    }
  },
  set: async (key, value) => {
    try {
      if (window.storage) {
        await window.storage.set(key, JSON.stringify(value));
      } else {
        localStorage.setItem(key, JSON.stringify(value));
      }
    } catch {}
  },
  delete: async (key) => {
    try {
      if (window.storage) await window.storage.delete(key);
      else localStorage.removeItem(key);
    } catch {}
  },
};

export default function TravelBlog() {
  const [currentPage, setCurrentPage] = useState("home");
  const [stories, setStories] = useState(sampleStories);
  const [selectedStory, setSelectedStory] = useState(null);
  const [showToast, setShowToast] = useState(null);
  const [likedStories, setLikedStories] = useState(new Set());
  const [bookmarkedStories, setBookmarkedStories] = useState(new Set());
  const [isLoading, setIsLoading] = useState(true);

  // Admin state
  const [isAdmin, setIsAdmin] = useState(false);
  const [showAdminLogin, setShowAdminLogin] = useState(false);
  const [adminUsername, setAdminUsername] = useState("");
  const [adminPassword, setAdminPassword] = useState("");
  const [adminLoginError, setAdminLoginError] = useState("");
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(null);

  // Search and filter
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedCategory, setSelectedCategory] = useState("All");
  const [sortBy, setSortBy] = useState("newest");
  const [viewMode, setViewMode] = useState("grid");
  const [showFilters, setShowFilters] = useState(false);

  // User state
  const [newComment, setNewComment] = useState("");
  const [userName, setUserName] = useState("");
  const [showUserModal, setShowUserModal] = useState(false);

  // New story form
  const [newStory, setNewStory] = useState({
    title: "",
    excerpt: "",
    content: "",
    category: "",
    location: "",
    coverImagePreview: "",
  });
  const fileInputRef = useRef(null);

  // Load data
  useEffect(() => {
    const loadData = async () => {
      setIsLoading(true);
      const savedStories = await Storage.get("Krissane-stories");
      const savedLikes = await Storage.get("Krissane-likes");
      const savedBookmarks = await Storage.get("Krissane-bookmarks");
      const savedUserName = await Storage.get("Krissane-username");
      const savedAdmin = await Storage.get("Krissane-admin");

      if (savedStories?.length > 0) setStories(savedStories);
      if (savedLikes) setLikedStories(new Set(savedLikes));
      if (savedBookmarks) setBookmarkedStories(new Set(savedBookmarks));
      if (savedUserName) setUserName(savedUserName);
      if (savedAdmin) setIsAdmin(true);
      setIsLoading(false);
    };
    loadData();
  }, []);

  // Save data
  useEffect(() => {
    if (!isLoading) Storage.set("Krissane-stories", stories);
  }, [stories, isLoading]);
  useEffect(() => {
    if (!isLoading) Storage.set("Krissane-likes", Array.from(likedStories));
  }, [likedStories, isLoading]);
  useEffect(() => {
    if (!isLoading)
      Storage.set("Krissane-bookmarks", Array.from(bookmarkedStories));
  }, [bookmarkedStories, isLoading]);

  const toast = (message, type = "success") => {
    setShowToast({ message, type });
    setTimeout(() => setShowToast(null), 3000);
  };

  // Admin functions
  const handleAdminLogin = () => {
    if (
      adminUsername === ADMIN_CREDENTIALS.username &&
      adminPassword === ADMIN_CREDENTIALS.password
    ) {
      setIsAdmin(true);
      setShowAdminLogin(false);
      setAdminUsername("");
      setAdminPassword("");
      setAdminLoginError("");
      Storage.set("Krissane-admin", true);
      toast("Welcome, Admin! 🛡️");
    } else {
      setAdminLoginError("Invalid username or password");
    }
  };

  const handleAdminLogout = () => {
    setIsAdmin(false);
    Storage.delete("Krissane-admin");
    toast("Logged out successfully");
  };

  // Filter stories
  const filteredStories = stories
    .filter((story) => {
      const matchesSearch =
        story.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        story.excerpt.toLowerCase().includes(searchQuery.toLowerCase()) ||
        story.location.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesCategory =
        selectedCategory === "All" || story.category === selectedCategory;
      return matchesSearch && matchesCategory;
    })
    .sort((a, b) => {
      if (sortBy === "newest") return new Date(b.date) - new Date(a.date);
      if (sortBy === "oldest") return new Date(a.date) - new Date(b.date);
      if (sortBy === "popular") return b.likes - a.likes;
      return (b.comments?.length || 0) - (a.comments?.length || 0);
    });

  const handleImageUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () =>
        setNewStory((prev) => ({ ...prev, coverImagePreview: reader.result }));
      reader.readAsDataURL(file);
    }
  };

  const handleSubmitStory = () => {
    if (!newStory.title || !newStory.content || !newStory.category) {
      toast("Please fill in title, content, and category", "error");
      return;
    }
    const story = {
      id: Date.now(),
      title: newStory.title,
      excerpt: newStory.excerpt || newStory.content.substring(0, 150) + "...",
      content: newStory.content,
      category: newStory.category,
      location: newStory.location || "Unknown Location",
      date: new Date().toISOString().split("T")[0],
      readTime: Math.max(
        1,
        Math.ceil(newStory.content.split(" ").length / 200)
      ),
      coverImage:
        newStory.coverImagePreview ||
        "https://images.unsplash.com/photo-1488646953014-85cb44e25828?w=1200&h=800&fit=crop",
      author: {
        name: userName || "Anonymous Traveler",
        avatar:
          "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=100&h=100&fit=crop",
      },
      likes: 0,
      comments: [],
    };
    setStories((prev) => [story, ...prev]);
    setNewStory({
      title: "",
      excerpt: "",
      content: "",
      category: "",
      location: "",
      coverImagePreview: "",
    });
    setCurrentPage("home");
    toast("Your story has been published! 🎉");
  };

  const handleLike = (storyId, e) => {
    if (e) e.stopPropagation();
    const isLiked = likedStories.has(storyId);
    setLikedStories((prev) => {
      const newSet = new Set(prev);
      isLiked ? newSet.delete(storyId) : newSet.add(storyId);
      return newSet;
    });
    setStories((prev) =>
      prev.map((s) =>
        s.id === storyId
          ? { ...s, likes: isLiked ? s.likes - 1 : s.likes + 1 }
          : s
      )
    );
    if (selectedStory?.id === storyId) {
      setSelectedStory((prev) => ({
        ...prev,
        likes: isLiked ? prev.likes - 1 : prev.likes + 1,
      }));
    }
  };

  const handleBookmark = (storyId, e) => {
    if (e) e.stopPropagation();
    setBookmarkedStories((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(storyId)) {
        newSet.delete(storyId);
        toast("Removed from bookmarks");
      } else {
        newSet.add(storyId);
        toast("Added to bookmarks");
      }
      return newSet;
    });
  };

  const handleAddComment = () => {
    if (!newComment.trim()) {
      toast("Please write a comment", "error");
      return;
    }
    if (!userName) {
      setShowUserModal(true);
      return;
    }
    const comment = {
      id: Date.now(),
      author: userName,
      avatar:
        "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=100&h=100&fit=crop",
      text: newComment,
      date: new Date().toISOString().split("T")[0],
    };
    setStories((prev) =>
      prev.map((s) =>
        s.id === selectedStory.id
          ? { ...s, comments: [...(s.comments || []), comment] }
          : s
      )
    );
    setSelectedStory((prev) => ({
      ...prev,
      comments: [...(prev.comments || []), comment],
    }));
    setNewComment("");
    toast("Comment added!");
  };

  const handleSaveUserName = () => {
    if (userName.trim()) {
      Storage.set("Krissane-username", userName);
      setShowUserModal(false);
      if (newComment.trim()) handleAddComment();
    }
  };

  // Delete functions
  const handleDeleteStory = (storyId) => {
    setStories((prev) => prev.filter((s) => s.id !== storyId));
    setSelectedStory(null);
    setCurrentPage("home");
    setShowDeleteConfirm(null);
    toast("Story deleted successfully");
  };

  const handleDeleteComment = (storyId, commentId) => {
    setStories((prev) =>
      prev.map((s) =>
        s.id === storyId
          ? { ...s, comments: s.comments.filter((c) => c.id !== commentId) }
          : s
      )
    );
    if (selectedStory?.id === storyId) {
      setSelectedStory((prev) => ({
        ...prev,
        comments: prev.comments.filter((c) => c.id !== commentId),
      }));
    }
    setShowDeleteConfirm(null);
    toast("Comment deleted");
  };

  const canDeleteStory = (story) =>
    isAdmin || story.author.name === (userName || "Anonymous Traveler");

  if (isLoading) {
    return (
      <div style={styles.loadingScreen}>
        <div style={styles.loadingSpinner}></div>
        <p>Loading your adventures...</p>
      </div>
    );
  }

  return (
    <div style={styles.app}>
      {/* Toast */}
      {showToast && (
        <div
          style={{
            ...styles.toast,
            background: showToast.type === "error" ? "#e74c3c" : "#27ae60",
          }}
        >
          {showToast.type === "success" ? <Icons.Check /> : <Icons.X />}
          {showToast.message}
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {showDeleteConfirm && (
        <div
          style={styles.modalOverlay}
          onClick={() => setShowDeleteConfirm(null)}
        >
          <div style={styles.modal} onClick={(e) => e.stopPropagation()}>
            <div style={styles.deleteModalIcon}>
              <Icons.AlertTriangle />
            </div>
            <h3 style={styles.modalTitle}>Delete {showDeleteConfirm.type}?</h3>
            <p style={styles.modalDesc}>
              {showDeleteConfirm.type === "story"
                ? "This will permanently delete this story and all its comments."
                : "This will permanently delete this comment."}
            </p>
            <div style={styles.modalActions}>
              <button
                onClick={() => setShowDeleteConfirm(null)}
                style={styles.cancelBtn}
              >
                Cancel
              </button>
              <button
                onClick={() => {
                  if (showDeleteConfirm.type === "story")
                    handleDeleteStory(showDeleteConfirm.id);
                  else
                    handleDeleteComment(
                      showDeleteConfirm.storyId,
                      showDeleteConfirm.id
                    );
                }}
                style={styles.deleteConfirmBtn}
              >
                <Icons.Trash /> Delete
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Admin Login Modal */}
      {showAdminLogin && (
        <div
          style={styles.modalOverlay}
          onClick={() => setShowAdminLogin(false)}
        >
          <div style={styles.modal} onClick={(e) => e.stopPropagation()}>
            <div style={styles.adminLoginHeader}>
              <div style={styles.adminIconBig}>
                <Icons.Shield />
              </div>
              <h3 style={styles.modalTitle}>Admin Login</h3>
            </div>
            <p style={styles.modalDesc}>
              Enter your credentials to access moderation features.
            </p>
            {adminLoginError && (
              <div style={styles.loginError}>
                <Icons.AlertTriangle /> {adminLoginError}
              </div>
            )}
            <div style={styles.loginForm}>
              <input
                type="text"
                placeholder="Username"
                value={adminUsername}
                onChange={(e) => setAdminUsername(e.target.value)}
                style={styles.modalInput}
                autoFocus
              />
              <input
                type="password"
                placeholder="Password"
                value={adminPassword}
                onChange={(e) => setAdminPassword(e.target.value)}
                style={styles.modalInput}
                onKeyPress={(e) => e.key === "Enter" && handleAdminLogin()}
              />
            </div>
            <div style={styles.modalActions}>
              <button
                onClick={() => setShowAdminLogin(false)}
                style={styles.cancelBtn}
              >
                Cancel
              </button>
              <button onClick={handleAdminLogin} style={styles.adminLoginBtn}>
                <Icons.Lock /> Login
              </button>
            </div>
            <div style={styles.adminHint}>
              <strong>Demo:</strong> Krissaneadmin / Krissane2026
            </div>
          </div>
        </div>
      )}

      {/* Username Modal */}
      {showUserModal && (
        <div
          style={styles.modalOverlay}
          onClick={() => setShowUserModal(false)}
        >
          <div style={styles.modal} onClick={(e) => e.stopPropagation()}>
            <h3 style={styles.modalTitle}>What's your name?</h3>
            <p style={styles.modalDesc}>
              This will be shown with your comments and stories.
            </p>
            <input
              type="text"
              placeholder="Enter your name"
              value={userName}
              onChange={(e) => setUserName(e.target.value)}
              style={styles.modalInput}
              autoFocus
            />
            <div style={styles.modalActions}>
              <button
                onClick={() => setShowUserModal(false)}
                style={styles.cancelBtn}
              >
                Cancel
              </button>
              <button onClick={handleSaveUserName} style={styles.publishBtn}>
                Save
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Navigation */}
      <nav style={styles.nav}>
        <a href="#" onClick={() => setCurrentPage("home")} style={styles.logo}>
          Krissane<span style={styles.logoAccent}>.</span>
        </a>
        <div style={styles.navLinks}>
          <a
            href="#"
            onClick={() => setCurrentPage("home")}
            style={styles.navLink}
          >
            Stories
          </a>
          <a
            href="#"
            onClick={() => setCurrentPage("bookmarks")}
            style={styles.navLink}
          >
            Bookmarks{" "}
            {bookmarkedStories.size > 0 && (
              <span style={styles.badge}>{bookmarkedStories.size}</span>
            )}
          </a>
          <a
            href="#"
            onClick={() => setCurrentPage("guide")}
            style={styles.navLink}
          >
            Writing Guide
          </a>
          <button
            onClick={() => setCurrentPage("create")}
            style={styles.createBtn}
          >
            <Icons.Plus /> New Story
          </button>

          {isAdmin ? (
            <div style={styles.adminBadgeContainer}>
              <div style={styles.adminBadge}>
                <Icons.Shield /> Admin
              </div>
              <button
                onClick={handleAdminLogout}
                style={styles.logoutBtn}
                title="Logout"
              >
                <Icons.LogOut />
              </button>
            </div>
          ) : (
            <button
              onClick={() => setShowAdminLogin(true)}
              style={styles.adminLoginNavBtn}
              title="Admin Login"
            >
              <Icons.Lock />
            </button>
          )}

          <button
            onClick={() => setShowUserModal(true)}
            style={styles.userBtn}
            title={userName || "Set your name"}
          >
            <Icons.User />
            {userName && (
              <span style={styles.userNameDisplay}>
                {userName.split(" ")[0]}
              </span>
            )}
          </button>
        </div>
      </nav>

      {/* Admin Banner */}
      {isAdmin && (
        <div style={styles.adminBanner}>
          <Icons.Shield /> Admin Mode — You can delete any posts and comments
        </div>
      )}

      {/* Main Content */}
      <main style={styles.main}>
        {/* HOME */}
        {currentPage === "home" && (
          <>
            <section style={styles.hero}>
              <div style={styles.heroContent}>
                <span style={styles.heroTag}>Travel Stories That Move You</span>
                <h1 style={styles.heroTitle}>
                  Every Journey Deserves to Be{" "}
                  <em style={styles.heroEmphasis}>Told</em>
                </h1>
                <p style={styles.heroDesc}>
                  Discover the art of travel storytelling. Share your adventures
                  with authentic voice, sensory details, and the moments that
                  changed you forever.
                </p>
                <div style={styles.heroCta}>
                  <button
                    onClick={() => setCurrentPage("create")}
                    style={styles.btnPrimary}
                  >
                    Share Your Story →
                  </button>
                  <button
                    onClick={() => setCurrentPage("guide")}
                    style={styles.btnSecondary}
                  >
                    Learn to Write
                  </button>
                </div>
              </div>
              <div style={styles.heroImageWrapper}>
                <img src="/2.jpeg" alt="Traveler" style={styles.heroImage} />
                <div style={styles.heroStats}>
                  <div style={styles.stat}>
                    <div style={styles.statNumber}>{stories.length}</div>
                    <div style={styles.statLabel}>Stories</div>
                  </div>
                  <div style={styles.stat}>
                    <div style={styles.statNumber}>
                      {stories.reduce(
                        (acc, s) => acc + (s.comments?.length || 0),
                        0
                      )}
                    </div>
                    <div style={styles.statLabel}>Comments</div>
                  </div>
                </div>
              </div>
            </section>

            {/* Search & Filters */}
            <section style={styles.filterSection}>
              <div style={styles.searchBar}>
                <Icons.Search />
                <input
                  type="text"
                  placeholder="Search stories..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  style={styles.searchInput}
                />
                {searchQuery && (
                  <button
                    onClick={() => setSearchQuery("")}
                    style={styles.clearSearch}
                  >
                    <Icons.X />
                  </button>
                )}
              </div>
              <div style={styles.filterControls}>
                <button
                  onClick={() => setShowFilters(!showFilters)}
                  style={{
                    ...styles.filterBtn,
                    background: showFilters ? "#C4704F" : "#f5f5f5",
                    color: showFilters ? "white" : "#666",
                  }}
                >
                  <Icons.Filter /> Filters
                </button>
                <div style={styles.viewToggle}>
                  <button
                    onClick={() => setViewMode("grid")}
                    style={{
                      ...styles.viewBtn,
                      background:
                        viewMode === "grid" ? "#2C2C2C" : "transparent",
                      color: viewMode === "grid" ? "white" : "#666",
                    }}
                  >
                    <Icons.Grid />
                  </button>
                  <button
                    onClick={() => setViewMode("list")}
                    style={{
                      ...styles.viewBtn,
                      background:
                        viewMode === "list" ? "#2C2C2C" : "transparent",
                      color: viewMode === "list" ? "white" : "#666",
                    }}
                  >
                    <Icons.List />
                  </button>
                </div>
              </div>
            </section>

            {showFilters && (
              <section style={styles.expandedFilters}>
                <div style={styles.filterGroup}>
                  <label style={styles.filterLabel}>Category</label>
                  <div style={styles.categoryPills}>
                    {categories.map((cat) => (
                      <button
                        key={cat}
                        onClick={() => setSelectedCategory(cat)}
                        style={{
                          ...styles.categoryPill,
                          background:
                            selectedCategory === cat ? "#C4704F" : "white",
                          color: selectedCategory === cat ? "white" : "#666",
                        }}
                      >
                        {cat}
                      </button>
                    ))}
                  </div>
                </div>
                <div style={styles.filterGroup}>
                  <label style={styles.filterLabel}>Sort by</label>
                  <select
                    value={sortBy}
                    onChange={(e) => setSortBy(e.target.value)}
                    style={styles.sortSelect}
                  >
                    <option value="newest">Newest First</option>
                    <option value="oldest">Oldest First</option>
                    <option value="popular">Most Liked</option>
                    <option value="comments">Most Discussed</option>
                  </select>
                </div>
              </section>
            )}

            {/* Stories Grid */}
            <section style={styles.storiesSection}>
              <div
                style={
                  viewMode === "grid" ? styles.storiesGrid : styles.storiesList
                }
              >
                {filteredStories.map((story, index) => (
                  <article
                    key={story.id}
                    style={{
                      ...styles.storyCard,
                      ...(viewMode === "grid" && index === 0
                        ? styles.storyCardFeatured
                        : {}),
                      ...(viewMode === "list" ? styles.storyCardList : {}),
                    }}
                    onClick={() => {
                      setSelectedStory(story);
                      setCurrentPage("story");
                    }}
                  >
                    <div
                      style={{
                        ...styles.storyImageWrapper,
                        ...(viewMode === "list"
                          ? styles.storyImageWrapperList
                          : {}),
                      }}
                    >
                      <img
                        src={story.coverImage}
                        alt={story.title}
                        style={styles.storyImage}
                      />
                      <div style={styles.storyOverlay}>
                        <span style={styles.readMore}>Read Story →</span>
                      </div>
                      <div style={styles.storyActions}>
                        <button
                          onClick={(e) => handleLike(story.id, e)}
                          style={{
                            ...styles.actionIconBtn,
                            color: likedStories.has(story.id)
                              ? "#e74c3c"
                              : "white",
                          }}
                        >
                          <Icons.Heart filled={likedStories.has(story.id)} />
                        </button>
                        <button
                          onClick={(e) => handleBookmark(story.id, e)}
                          style={{
                            ...styles.actionIconBtn,
                            color: bookmarkedStories.has(story.id)
                              ? "#f39c12"
                              : "white",
                          }}
                        >
                          <Icons.Bookmark
                            filled={bookmarkedStories.has(story.id)}
                          />
                        </button>
                        {isAdmin && (
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              setShowDeleteConfirm({
                                type: "story",
                                id: story.id,
                              });
                            }}
                            style={{
                              ...styles.actionIconBtn,
                              color: "#e74c3c",
                            }}
                            title="Delete (Admin)"
                          >
                            <Icons.Trash />
                          </button>
                        )}
                      </div>
                    </div>
                    <div style={styles.storyContent}>
                      <span style={styles.storyCategory}>{story.category}</span>
                      <h3
                        style={{
                          ...styles.storyTitle,
                          fontSize:
                            viewMode === "grid" && index === 0
                              ? "1.6rem"
                              : "1.2rem",
                        }}
                      >
                        {story.title}
                      </h3>
                      <p style={styles.storyExcerpt}>{story.excerpt}</p>
                      <div style={styles.storyMeta}>
                        <div style={styles.storyAuthor}>
                          <img
                            src={story.author.avatar}
                            alt={story.author.name}
                            style={styles.authorAvatar}
                          />
                          <span>{story.author.name}</span>
                        </div>
                        <div style={styles.storyStats}>
                          <span style={styles.metaItem}>
                            <Icons.Clock /> {story.readTime}m
                          </span>
                          <span style={styles.metaItem}>
                            <Icons.Heart filled={false} /> {story.likes}
                          </span>
                          <span style={styles.metaItem}>
                            <Icons.MessageCircle />{" "}
                            {story.comments?.length || 0}
                          </span>
                        </div>
                      </div>
                    </div>
                  </article>
                ))}
              </div>
            </section>
          </>
        )}

        {/* BOOKMARKS */}
        {currentPage === "bookmarks" && (
          <div style={styles.bookmarksPage}>
            <button
              onClick={() => setCurrentPage("home")}
              style={styles.backBtn}
            >
              <Icons.ArrowLeft /> Back to Stories
            </button>
            <div style={styles.pageHeader}>
              <h1 style={styles.pageTitle}>
                Your <em style={styles.titleEmphasis}>Bookmarks</em>
              </h1>
              <p style={styles.pageSubtitle}>
                Stories you've saved for later reading
              </p>
            </div>
            {bookmarkedStories.size === 0 ? (
              <div style={styles.emptyState}>
                <Icons.Bookmark filled={false} />
                <h3>No bookmarks yet</h3>
                <p>Save stories to read later</p>
                <button
                  onClick={() => setCurrentPage("home")}
                  style={styles.btnPrimary}
                >
                  Browse Stories
                </button>
              </div>
            ) : (
              <div style={styles.storiesGrid}>
                {stories
                  .filter((s) => bookmarkedStories.has(s.id))
                  .map((story) => (
                    <article
                      key={story.id}
                      style={styles.storyCard}
                      onClick={() => {
                        setSelectedStory(story);
                        setCurrentPage("story");
                      }}
                    >
                      <div style={styles.storyImageWrapper}>
                        <img
                          src={story.coverImage}
                          alt={story.title}
                          style={styles.storyImage}
                        />
                        <button
                          onClick={(e) => handleBookmark(story.id, e)}
                          style={styles.removeBookmark}
                        >
                          <Icons.X />
                        </button>
                      </div>
                      <div style={styles.storyContent}>
                        <span style={styles.storyCategory}>
                          {story.category}
                        </span>
                        <h3 style={styles.storyTitle}>{story.title}</h3>
                        <div style={styles.storyMeta}>
                          <span style={styles.metaItem}>
                            <Icons.Clock /> {story.readTime}m read
                          </span>
                        </div>
                      </div>
                    </article>
                  ))}
              </div>
            )}
          </div>
        )}

        {/* STORY VIEW */}
        {currentPage === "story" && selectedStory && (
          <article style={styles.articlePage}>
            <button
              onClick={() => setCurrentPage("home")}
              style={styles.backBtn}
            >
              <Icons.ArrowLeft /> Back to Stories
            </button>

            <header style={styles.articleHeader}>
              <span style={styles.articleCategory}>
                {selectedStory.category}
              </span>
              <h1 style={styles.articleTitle}>{selectedStory.title}</h1>
              <div style={styles.articleMeta}>
                <div style={styles.articleAuthor}>
                  <img
                    src={selectedStory.author.avatar}
                    alt={selectedStory.author.name}
                    style={styles.articleAvatar}
                  />
                  <div>
                    <div style={styles.authorName}>
                      {selectedStory.author.name}
                    </div>
                    <div style={styles.articleDate}>
                      {new Date(selectedStory.date).toLocaleDateString(
                        "en-US",
                        { year: "numeric", month: "long", day: "numeric" }
                      )}{" "}
                      • {selectedStory.location}
                    </div>
                  </div>
                </div>
                <div style={styles.articleInfo}>
                  <span>
                    <Icons.Clock /> {selectedStory.readTime} min read
                  </span>
                </div>
              </div>
            </header>

            <img
              src={selectedStory.coverImage}
              alt={selectedStory.title}
              style={styles.articleCover}
            />

            <div style={styles.articleBody}>
              {selectedStory.content.split("\n\n").map((p, i) => (
                <p key={i} style={styles.articleParagraph}>
                  {p}
                </p>
              ))}
            </div>

            <div style={styles.articleActionsBar}>
              <button
                onClick={() => handleLike(selectedStory.id)}
                style={{
                  ...styles.articleActionBtn,
                  background: likedStories.has(selectedStory.id)
                    ? "#ffeaea"
                    : "#f5f5f5",
                  color: likedStories.has(selectedStory.id)
                    ? "#e74c3c"
                    : "#666",
                }}
              >
                <Icons.Heart filled={likedStories.has(selectedStory.id)} />{" "}
                {selectedStory.likes} Likes
              </button>
              <button
                onClick={(e) => handleBookmark(selectedStory.id, e)}
                style={{
                  ...styles.articleActionBtn,
                  background: bookmarkedStories.has(selectedStory.id)
                    ? "#fff8e6"
                    : "#f5f5f5",
                  color: bookmarkedStories.has(selectedStory.id)
                    ? "#f39c12"
                    : "#666",
                }}
              >
                <Icons.Bookmark
                  filled={bookmarkedStories.has(selectedStory.id)}
                />{" "}
                {bookmarkedStories.has(selectedStory.id) ? "Saved" : "Save"}
              </button>
              <button
                onClick={() => {
                  navigator.clipboard.writeText(window.location.href);
                  toast("Link copied!");
                }}
                style={styles.articleActionBtn}
              >
                <Icons.Share /> Share
              </button>
              {canDeleteStory(selectedStory) && (
                <button
                  onClick={() =>
                    setShowDeleteConfirm({
                      type: "story",
                      id: selectedStory.id,
                    })
                  }
                  style={{ ...styles.articleActionBtn, ...styles.deleteBtn }}
                >
                  <Icons.Trash /> Delete{" "}
                  {isAdmin &&
                    selectedStory.author.name !== userName &&
                    "(Admin)"}
                </button>
              )}
            </div>

            {/* Comments */}
            <section style={styles.commentsSection}>
              <h3 style={styles.commentsTitle}>
                <Icons.MessageCircle /> Comments (
                {selectedStory.comments?.length || 0})
              </h3>

              <div style={styles.addComment}>
                <img
                  src="https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=100&h=100&fit=crop"
                  alt="You"
                  style={styles.commentAvatar}
                />
                <div style={styles.commentInputWrapper}>
                  <textarea
                    placeholder={
                      userName
                        ? `Share your thoughts, ${userName.split(" ")[0]}...`
                        : "Share your thoughts..."
                    }
                    value={newComment}
                    onChange={(e) => setNewComment(e.target.value)}
                    style={styles.commentInput}
                    rows={3}
                  />
                  <button
                    onClick={handleAddComment}
                    style={styles.commentSubmitBtn}
                  >
                    <Icons.Send /> Post
                  </button>
                </div>
              </div>

              <div style={styles.commentsList}>
                {selectedStory.comments?.length === 0 && (
                  <div style={styles.noComments}>
                    <p>No comments yet. Be the first!</p>
                  </div>
                )}
                {selectedStory.comments?.map((comment) => (
                  <div key={comment.id} style={styles.comment}>
                    <img
                      src={comment.avatar}
                      alt={comment.author}
                      style={styles.commentAvatar}
                    />
                    <div style={styles.commentBody}>
                      <div style={styles.commentHeader}>
                        <span style={styles.commentAuthor}>
                          {comment.author}
                        </span>
                        <span style={styles.commentDate}>
                          {new Date(comment.date).toLocaleDateString("en-US", {
                            month: "short",
                            day: "numeric",
                          })}
                        </span>
                        {isAdmin && (
                          <button
                            onClick={() =>
                              setShowDeleteConfirm({
                                type: "comment",
                                id: comment.id,
                                storyId: selectedStory.id,
                              })
                            }
                            style={styles.deleteCommentBtn}
                            title="Delete (Admin)"
                          >
                            <Icons.Trash />
                          </button>
                        )}
                      </div>
                      <p style={styles.commentText}>{comment.text}</p>
                    </div>
                  </div>
                ))}
              </div>
            </section>
          </article>
        )}

        {/* CREATE */}
        {currentPage === "create" && (
          <div style={styles.createPage}>
            <button
              onClick={() => setCurrentPage("home")}
              style={styles.backBtn}
            >
              <Icons.ArrowLeft /> Back to Stories
            </button>
            <div style={styles.createHeader}>
              <h1 style={styles.createTitle}>
                Share Your <em style={styles.titleEmphasis}>Story</em>
              </h1>
              <p style={styles.createSubtitle}>
                Tell us about your journey with sensory details and emotional
                depth.
              </p>
            </div>
            <div style={styles.createForm}>
              <div style={styles.imageUpload}>
                {newStory.coverImagePreview ? (
                  <div style={styles.imagePreviewWrapper}>
                    <img
                      src={newStory.coverImagePreview}
                      alt="Cover"
                      style={styles.imagePreview}
                    />
                    <button
                      onClick={() =>
                        setNewStory((prev) => ({
                          ...prev,
                          coverImagePreview: "",
                        }))
                      }
                      style={styles.removeImageBtn}
                    >
                      <Icons.X />
                    </button>
                  </div>
                ) : (
                  <div
                    style={styles.uploadPlaceholder}
                    onClick={() => fileInputRef.current?.click()}
                  >
                    <Icons.Image />
                    <span>Click to upload cover image</span>
                    <span style={styles.uploadHint}>
                      Recommended: 1200 x 800px
                    </span>
                  </div>
                )}
                <input
                  ref={fileInputRef}
                  type="file"
                  accept="image/*"
                  onChange={handleImageUpload}
                  style={{ display: "none" }}
                />
              </div>
              <input
                type="text"
                placeholder="Your story title..."
                value={newStory.title}
                onChange={(e) =>
                  setNewStory((prev) => ({ ...prev, title: e.target.value }))
                }
                style={styles.titleInput}
              />
              <div style={styles.formRow}>
                <select
                  value={newStory.category}
                  onChange={(e) =>
                    setNewStory((prev) => ({
                      ...prev,
                      category: e.target.value,
                    }))
                  }
                  style={styles.selectInput}
                >
                  <option value="">Select Category</option>
                  {categories
                    .filter((c) => c !== "All")
                    .map((cat) => (
                      <option key={cat} value={cat}>
                        {cat}
                      </option>
                    ))}
                </select>
                <input
                  type="text"
                  placeholder="Location (e.g., Tokyo, Japan)"
                  value={newStory.location}
                  onChange={(e) =>
                    setNewStory((prev) => ({
                      ...prev,
                      location: e.target.value,
                    }))
                  }
                  style={styles.locationInput}
                />
              </div>
              <textarea
                placeholder="Brief excerpt (optional)"
                value={newStory.excerpt}
                onChange={(e) =>
                  setNewStory((prev) => ({ ...prev, excerpt: e.target.value }))
                }
                style={styles.excerptInput}
                rows={2}
              />
              <textarea
                placeholder="Tell your story here..."
                value={newStory.content}
                onChange={(e) =>
                  setNewStory((prev) => ({ ...prev, content: e.target.value }))
                }
                style={styles.contentInput}
                rows={15}
              />
              <div style={styles.wordCount}>
                {newStory.content.split(/\s+/).filter(Boolean).length} words • ~
                {Math.max(
                  1,
                  Math.ceil(
                    newStory.content.split(/\s+/).filter(Boolean).length / 200
                  )
                )}{" "}
                min read
              </div>
              <div style={styles.formActions}>
                <button
                  onClick={() => setCurrentPage("home")}
                  style={styles.cancelBtn}
                >
                  Cancel
                </button>
                <button onClick={handleSubmitStory} style={styles.publishBtn}>
                  <Icons.Send /> Publish Story
                </button>
              </div>
            </div>
          </div>
        )}

        {/* GUIDE */}
        {currentPage === "guide" && (
          <div style={styles.guidePage}>
            <button
              onClick={() => setCurrentPage("home")}
              style={styles.backBtn}
            >
              <Icons.ArrowLeft /> Back to Stories
            </button>
            <div style={styles.guideHeader}>
              <span style={styles.sectionTag}>The Art of Travel Writing</span>
              <h1 style={styles.guideTitle}>
                Essential Elements of a{" "}
                <em style={styles.titleEmphasis}>Great Story</em>
              </h1>
            </div>
            <div style={styles.tipsGrid}>
              {writingTips.map((tip, i) => (
                <div key={i} style={styles.tipCard}>
                  <div style={styles.tipIcon}>{tip.icon}</div>
                  <h3 style={styles.tipTitle}>{tip.title}</h3>
                  <p style={styles.tipDesc}>{tip.desc}</p>
                </div>
              ))}
            </div>
            <div style={styles.structureSection}>
              <h2 style={styles.structureTitle}>
                <Icons.BookOpen /> Story Structure
              </h2>
              <div style={styles.structureSteps}>
                {[
                  {
                    num: "01",
                    title: "Hook",
                    desc: "Grab attention immediately",
                  },
                  {
                    num: "02",
                    title: "Context",
                    desc: "Where and why you went",
                  },
                  {
                    num: "03",
                    title: "Journey",
                    desc: "Walk through experiences",
                  },
                  { num: "04", title: "Reflection", desc: "What you learned" },
                ].map((step, i) => (
                  <div key={i} style={styles.structureStep}>
                    <div style={styles.stepNum}>{step.num}</div>
                    <div>
                      <h4 style={styles.stepTitle}>{step.title}</h4>
                      <p style={styles.stepDesc}>{step.desc}</p>
                    </div>
                  </div>
                ))}
              </div>
            </div>
            <div style={styles.guideFooter}>
              <button
                onClick={() => setCurrentPage("create")}
                style={styles.btnPrimary}
              >
                Start Writing →
              </button>
            </div>
          </div>
        )}
      </main>

      {/* Footer */}
      <footer style={styles.footer}>
        <div style={styles.footerContent}>
          <div style={styles.footerBrand}>
            <span style={styles.logo}>
              Krissane<span style={styles.logoAccent}>.</span>
            </span>
            <p style={styles.footerText}>
              Stories that transport you. Every journey deserves to be told.
            </p>
          </div>
          <div style={styles.footerLinks}>
            <a href="#" onClick={() => setCurrentPage("home")}>
              Stories
            </a>
            <a href="#" onClick={() => setCurrentPage("bookmarks")}>
              Bookmarks
            </a>
            <a href="#" onClick={() => setCurrentPage("guide")}>
              Writing Guide
            </a>
          </div>
        </div>
        <div style={styles.footerBottom}>© 2026 Krissane Adventures.</div>
      </footer>
    </div>
  );
}

